export const DEFAULT_LOCATION_MULTIPLIERS = [
    { location: 'Bangalore', multiplier: 1.15, sortOrder: 1 },
    { location: 'Hyderabad', multiplier: 1.1, sortOrder: 2 },
    { location: 'Pune', multiplier: 1.05, sortOrder: 3 },
    { location: 'Chennai', multiplier: 1.05, sortOrder: 4 },
    { location: 'Mumbai', multiplier: 1.2, sortOrder: 5 },
    { location: 'Delhi NCR', multiplier: 1.15, sortOrder: 6 },
];
function bands(b1, b2, b3, b4, b5, b6) {
    const labels = [
        '1-3 yrs',
        '3-4 yrs',
        '4-5 yrs',
        '5-6 yrs',
        '7-8 yrs',
        '9-10 yrs',
    ];
    const pairs = [b1, b2, b3, b4, b5, b6];
    return labels.map((experience, i) => ({
        experience,
        minCtc: pairs[i][0],
        maxCtc: pairs[i][1],
    }));
}
